declarefunctioncreate(): Container<HTMLDivElement, HTMLDivElement[]>;




declarefunctioncreate<extendsHTMLElement>(element: ): Container<, []>;




declarefunctioncreate<extendsHTMLElement, extendsHTMLElement>(




