returntypeofval === "string";





functionyell(str: any) {




if (isString(str)) {




returnstr.toUppercase();





throw"Oops!";




```

And just like type predicate signatures, these assertion signatures are incredibly expressive. We can express some fairly sophisticated ideas with these.
```

ts

functionassertIsDefined<T>(val: T): asserts valisNonNullable<T> {




if (val === undefined || val === null) {




thrownewAssertionError(




`Expected 'val' to be defined, but received ${val}`



    );




```

