 * Produces a blurred image from an input buffer.




 * @paraminput {Uint8Array}




 * @paramwidth {number}




 * @paramheight {number}



 */



exportfunctionblurImage(




input: Uint8Array,




width: number,




height: number




): Uint8Array;


```

